"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import AppShell from "@/components/Navbar";
import { api } from "@/lib/api";

interface FacultyLoadItem {
  instructor_id: number;
  full_name: string;
  dept_name: string | null;
  max_units: number;
  max_classes: number;
  current_units: number;
  current_classes: number;
  remaining_units: number;
  remaining_classes: number;
}

interface FacultyLoadResponse {
  success: boolean;
  message: string;
  data: FacultyLoadItem[];
  meta: { total: number; page: number; per_page: number };
}

const num = (value: unknown): number => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
};

function getLoadStatus(item: FacultyLoadItem): { label: string; cls: string } {
  const pct = item.max_units > 0 ? (item.current_units / item.max_units) * 100 : 0;
  if (item.current_units >= item.max_units) return { label: "At Limit", cls: "badge-red" };
  if (pct >= 80) return { label: "Near Limit", cls: "badge-yellow" };
  if (item.current_units === 0) return { label: "No Load", cls: "badge-gray" };
  return { label: "Within Limit", cls: "badge-green" };
}

export default function AdminFacultyLoadPage() {
  const [rows, setRows] = useState<FacultyLoadItem[]>([]);
  const [meta, setMeta] = useState({ total: 0, page: 1, per_page: 15 });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [deptFilter, setDeptFilter] = useState("All Departments");
  const [page, setPage] = useState(1);

  useEffect(() => {
    (async () => {
      try {
        setLoading(true);
        setError(null);
        const res = await api.get<FacultyLoadResponse>(`/admin/faculty-load?page=${page}`);
        setRows(
          (res.data ?? []).map((row) => ({
            ...row,
            max_units: num(row.max_units),
            max_classes: num(row.max_classes),
            current_units: num(row.current_units),
            current_classes: num(row.current_classes),
            remaining_units: num(row.remaining_units),
            remaining_classes: num(row.remaining_classes),
          }))
        );
        setMeta(res.meta ?? { total: 0, page, per_page: 15 });
      } catch (e) {
        setError(e instanceof Error ? e.message : "Failed to load faculty load.");
      } finally {
        setLoading(false);
      }
    })();
  }, [page]);

  const filteredData = useMemo(
    () =>
      rows.filter((f) => {
        const q = searchTerm.toLowerCase();
        const matchesSearch = !q || f.full_name.toLowerCase().includes(q) || String(f.instructor_id).includes(q);
        const matchesDept = deptFilter === "All Departments" || (f.dept_name ?? "N/A") === deptFilter;
        return matchesSearch && matchesDept;
      }),
    [rows, searchTerm, deptFilter]
  );

  const uniqueDepartments = useMemo(
    () => Array.from(new Set(rows.map((f) => f.dept_name ?? "N/A"))),
    [rows]
  );

  const atLimit = rows.filter((f) => f.current_units >= f.max_units).length;
  const nearLimit = rows.filter((f) => f.current_units < f.max_units && f.max_units > 0 && (f.current_units / f.max_units) * 100 >= 80).length;
  const noLoad = rows.filter((f) => f.current_units === 0).length;
  const totalPages = Math.max(1, Math.ceil(meta.total / meta.per_page));

  return (
    <AppShell role="admin" userName="Admin" pageTitle="Faculty Load Management">
      <div className="animate-fade-in space-y-6">
        <div>
          <h1 className="text-xl font-semibold" style={{ color: "var(--color-text)" }}>Faculty Load Management</h1>
          <p className="text-sm mt-0.5" style={{ color: "var(--color-text-secondary)" }}>
            Configure and monitor teaching load limits per instructor
          </p>
        </div>

        {error && <div className="rounded-lg border px-3 py-2 text-[12px]" style={{ borderColor: "#fecaca", background: "#fff1f2", color: "#9f1239" }}>{error}</div>}

        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <StatCard label="Total Instructors" value={String(meta.total)} />
          <StatCard label="At Load Limit" value={String(atLimit)} />
          <StatCard label="Near Limit (>=80%)" value={String(nearLimit)} />
          <StatCard label="No Load Assigned" value={String(noLoad)} />
        </div>

        <div className="card overflow-hidden">
          <div className="px-6 py-4 border-b flex items-center justify-between gap-3 flex-wrap" style={{ borderColor: "var(--color-border)" }}>
            <h2 className="text-sm font-semibold" style={{ color: "var(--color-text)" }}>All Instructors</h2>
            <div className="flex gap-2 items-center flex-wrap">
              <input placeholder="Search instructor..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} style={{ width: "200px" }} />
              <select value={deptFilter} onChange={(e) => setDeptFilter(e.target.value)} style={{ width: "180px" }}>
                <option value="All Departments">All Departments</option>
                {uniqueDepartments.map((dept) => <option key={dept} value={dept}>{dept}</option>)}
              </select>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="table-base w-full">
              <thead>
                <tr>
                  <th>Instructor</th><th>Department</th><th>Load Limit</th><th>Units Used</th><th>Classes</th><th>Status</th><th></th>
                </tr>
              </thead>
              <tbody>
                {filteredData.map((f) => {
                  const unitsPct = Math.min((f.current_units / (f.max_units || 1)) * 100, 100);
                  const status = getLoadStatus(f);
                  return (
                    <tr key={f.instructor_id}>
                      <td>
                        <p className="text-sm font-medium">{f.full_name}</p>
                        <p className="text-xs" style={{ color: "var(--color-text-muted)" }}>ID: {f.instructor_id}</p>
                      </td>
                      <td><span className="badge badge-blue">{f.dept_name ?? "N/A"}</span></td>
                      <td>{f.max_units} units / {f.max_classes} classes</td>
                      <td style={{ minWidth: "160px" }}>
                        <div className="space-y-1">
                          <div className="flex justify-between text-xs"><span>{f.current_units.toFixed(1)}</span><span>{f.max_units.toFixed(1)}</span></div>
                          <div className="h-1.5 rounded-full overflow-hidden" style={{ background: "var(--color-surface-2)" }}>
                            <div className="h-full rounded-full" style={{ width: `${unitsPct}%`, background: unitsPct >= 100 ? "var(--color-error)" : unitsPct >= 80 ? "var(--color-warning)" : "var(--color-primary-light)" }} />
                          </div>
                        </div>
                      </td>
                      <td>{f.current_classes} / {f.max_classes}</td>
                      <td><span className={`badge ${status.cls}`}>{status.label}</span></td>
                      <td><Link href={`/admin/faculty-load/${f.instructor_id}`} className="btn btn-sm btn-outline">Manage</Link></td>
                    </tr>
                  );
                })}
                {!loading && filteredData.length === 0 && (
                  <tr><td colSpan={7} className="text-center py-8 text-sm" style={{ color: "var(--color-text-muted)" }}>No instructors found.</td></tr>
                )}
              </tbody>
            </table>
          </div>

          <div className="px-6 py-3 border-t flex items-center justify-between text-xs" style={{ borderColor: "var(--color-border)", color: "var(--color-text-muted)" }}>
            <span>Showing {filteredData.length} of {meta.total} instructors</span>
            <div className="flex gap-1">
              <button className="btn btn-sm btn-ghost" disabled={page <= 1} onClick={() => setPage((p) => Math.max(1, p - 1))}>← Prev</button>
              <button className="btn btn-sm btn-ghost" disabled={page >= totalPages} onClick={() => setPage((p) => Math.min(totalPages, p + 1))}>Next →</button>
            </div>
          </div>
        </div>
      </div>
    </AppShell>
  );
}

function StatCard({ label, value }: { label: string; value: string }) {
  return (
    <div className="card card-body">
      <p className="text-xl font-bold leading-none" style={{ color: "var(--color-text)" }}>{value}</p>
      <p className="text-xs mt-0.5" style={{ color: "var(--color-text-secondary)" }}>{label}</p>
    </div>
  );
}
